CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY, name VARCHAR(150) NOT NULL, email VARCHAR(150) UNIQUE NOT NULL, password_hash TEXT NOT NULL, role VARCHAR(30) NOT NULL DEFAULT 'applicant', phone VARCHAR(20), state VARCHAR(100), district VARCHAR(100), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS schemes (id SERIAL PRIMARY KEY, name VARCHAR(200) NOT NULL, description TEXT, income_limit NUMERIC, min_marks NUMERIC, required_documents JSONB NOT NULL DEFAULT '[]'::jsonb, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS applications (id SERIAL PRIMARY KEY, application_number VARCHAR(60) UNIQUE NOT NULL, applicant_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, scheme_id INTEGER REFERENCES schemes(id), status VARCHAR(40) NOT NULL DEFAULT 'draft', form_data JSONB NOT NULL DEFAULT '{}'::jsonb, ai_risk_score NUMERIC, ocr_confidence NUMERIC, officer_remarks TEXT, submitted_at TIMESTAMP, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS documents (id SERIAL PRIMARY KEY, application_id INTEGER NOT NULL REFERENCES applications(id) ON DELETE CASCADE, document_type VARCHAR(100) NOT NULL, original_filename VARCHAR(255), stored_filename VARCHAR(255), file_path TEXT, extracted_text TEXT, ocr_confidence NUMERIC, ai_generated_probability NUMERIC, verification_status VARCHAR(40) DEFAULT 'pending', uploaded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS deficiencies (id SERIAL PRIMARY KEY, application_id INTEGER NOT NULL REFERENCES applications(id) ON DELETE CASCADE, document_id INTEGER REFERENCES documents(id) ON DELETE SET NULL, reason TEXT NOT NULL, status VARCHAR(30) DEFAULT 'open', applicant_response TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_logs (id SERIAL PRIMARY KEY, user_id INTEGER REFERENCES users(id), application_id INTEGER REFERENCES applications(id), action VARCHAR(100) NOT NULL, remarks TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
INSERT INTO schemes (name, description, income_limit, min_marks, required_documents) SELECT 'Tribal Student Merit Scholarship', 'Support for eligible Scheduled Tribe students with strong academic performance.', 250000, 60, '["income_certificate", "caste_certificate", "marksheet", "bank_passbook"]'::jsonb WHERE NOT EXISTS (SELECT 1 FROM schemes);
